function setCopilotOpen(open){const drawer=$('#copilotDrawer');if(!drawer)return;drawer.hidden=!open;drawer.setAttribute('aria-hidden',open?'false':'true');$('#copilotFab')?.setAttribute('aria-expanded',open?'true':'false');if(open){updateCopilotContext();setTimeout(()=>$('#copilotQuestion')?.focus(),0)}}
function toggleCopilot(){const drawer=$('#copilotDrawer');if(!drawer)return;setCopilotOpen(drawer.hidden)}
function updateCopilotContext(){const label=$('#copilotContext'),mode=$('#copilotMode');if(label){if(active){try{const d=L.dossier(db,active);label.textContent=`${d.application.id} · ${d.member.name} · ${d.application.product}`}catch{label.textContent='Dossier non accessible'}}else label.textContent='Contexte général CREDIPASS'}if(mode)mode.textContent=connectionState()==='HORS_CONNEXION'?'Mode hors connexion — assistant local':'IA connectée si fournisseur configuré';}
document.addEventListener('submit',e=>{if(e.target.id==='copilotForm'){e.preventDefault();const q=$('#copilotQuestion')?.value?.trim();if(q){act('copilotAsk',{dataset:{question:q}});$('#copilotQuestion').value=''}}});
document.addEventListener('click',e=>{const n=e.target.closest('[data-nav]');if(n){view=n.dataset.nav;active=null;render();return}const a=e.target.closest('[data-act]');if(a)act(a.dataset.act,a)});
$('#copilotFab')?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();toggleCopilot()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#copilotDrawer')?.hidden)setCopilotOpen(false)});document.addEventListener('input',e=>{if(e.target.id==='memberSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('tr[data-search]').forEach(r=>r.hidden=!r.dataset.search.includes(q))}});window.addEventListener('error',e=>{const b=$('#bootError');if(b){b.textContent='Erreur : '+e.message;b.hidden=false}});
function friendlyNetworkError(err){const m=String(err?.message||err||'');if(/Failed to fetch|fetch failed|NetworkError|Load failed/i.test(m))return 'Serveur CREDIPASS inaccessible. Vérifiez la fenêtre serveur et /api/health. Si le serveur ne démarre pas, vérifiez PostgreSQL avec « npm run db:check ».';return m||'Erreur inconnue.'}
const login=$('#institutionLogin'), loginScreen=$('#loginScreen'), appShell=$('#appShell');
function enterInstitution(user){currentUser=user||currentUser;loginScreen.hidden=true;appShell.hidden=false;sessionStorage.setItem('credipass-institution-user',JSON.stringify(currentUser));$('#userName').textContent=currentUser.name;$('#userName').nextElementSibling.textContent=currentUser.agency;render()}
async function leaveInstitution(){sessionStorage.removeItem('credipass-institution-user');await apiLogout();currentUser=null;appShell.hidden=true;loginScreen.hidden=false}
login?.addEventListener('submit',async e=>{e.preventDefault();const u=$('#loginUser').value.trim(),p=$('#loginPass').value;try{if(connectionState()==='HORS_CONNEXION'){const cached=await verifyOfflineLogin(u,p);enterInstitution(cached);return}const user=await apiLogin(u,p);enterInstitution(user)}catch(err){alert(friendlyNetworkError(err)||'Identifiant ou mot de passe incorrect.')}});
$('#logoutBtn')?.addEventListener('click',leaveInstitution);

async function restoreInstitutionSession(){let saved=null;try{saved=JSON.parse(sessionStorage.getItem('credipass-institution-user')||'null')}catch{}if(!saved)return;if(connectionState()==='HORS_CONNEXION'){enterInstitution(saved);return}const verified=await apiMe();if(verified)enterInstitution(verified);else sessionStorage.removeItem('credipass-institution-user')}
restoreInstitutionSession().catch(()=>sessionStorage.removeItem('credipass-institution-user'));
L.hydrate().then(x=>{db=ensureSfdFieldConfig(normalizeTerritory(ensureCatalog(normalizeScope(x))));if(!appShell.hidden)render()}).catch(()=>{});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

window.addEventListener('online',()=>render());window.addEventListener('offline',()=>render());window.addEventListener('credipass-connectivity',()=>render());
